{"command":"$dir='./'
$js = @'
const fs=require('fs'),crypto=require('crypto'),path=require('path');
const dir=process.argv[2];
const tmp=path.join(dir,'_body.tmp.md'), out=path.join(dir,'99b-v5-修订与终局判定.md');
let s=fs.readFileSync(tmp,'utf8');
s=s.replace(/\r\n/g,'\n');
// 去掉末尾换行，得到"末尾不含换行符的正文"
while(s.endsWith('\n')) s=s.slice(0,-1);
if(s.includes('\r')) throw new Error('CR remains');
const buf=Buffer.from(s,'utf8');
const sha=crypto.createHash('sha256').update(buf).digest('hex').slice(0,12);
const ev='EVIDENCE: '+out+'|'+buf.length+'|'+sha;
const final=s+'\n\n'+ev+'\n';
fs.writeFileSync(out, Buffer.from(final,'utf8'));
console.log(JSON.stringify({out,bytes:buf.length,sha12:sha,evidence:ev,finalBytes:Buffer.from(final,'utf8').length}));
'@
$tmpjs = Join-Path $env:TEMP 'mk99b.cjs'
Set-Content -Path $tmpjs -Value $js -Encoding UTF8
node $tmpjs $dir
Remove-Item $tmpjs -Force
Remove-Item (Join-Path $dir '_body.tmp.md') -Force
$f = Join-Path $dir '99b-v5-修订与终局判定.md'
$b = [System.IO.File]::ReadAllBytes($f)
"first3bytes: {0} {1} {2}" -f $b[0],$b[1],$b[2]
"hasCR: " + ([System.Text.Encoding]::UTF8.GetString($b)).Contains("`r")
"tail: " ; (Get-Content $f -Tail 2) -join ' || '","description":"合成终稿并计算字节与哈希"}

